    int leapYearCount = 0;
    while (N > 0) {
        if (isLeapYear(Y)) {
            leapYearCount++;
            if (leapYearCount == N) {
                return Y;
            }
        }
        Y++;
        N--;
    }
    throw new IllegalArgumentException("N must be positive");
}

