public static List<List<Integer>> permute(int[] nums) {
    if (nums.length == 1) {
      return Arrays.asList(new ArrayList<>(Arrays.asList(nums)));
    }

    List<List<Integer>> result = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
      int num = nums[i];
      int[] remainingNums = new int[nums.length - 1];
      for (int j = 0; j < i; j++) {
        remainingNums[j] = nums[j];
      }
      for (int j = i + 1; j < nums.length; j++) {
        remainingNums[j - 1] = nums[j];
      }

      List<List<Integer>> permutations = permute(remainingNums);
      for (List<Integer> permutation : permutations) {
        List<Integer> newPermutation = new ArrayList<>();
        newPermutation.add(num);
        newPermutation.addAll(permutation);
        result.add(newPermutation);
      }
    }

    return result;
  }

