    int largest = 0;
    for (String s : strings) {
        int len = s.length();
        if (len > largest) {
            largest = len;
        }
        for (int i = 0; i < len; i++) {
            String sub = s.substring(i);
            if (sub.length() == len && strings.contains(sub) || strings.contains(sub.reverse())) {
                return len;
            }
        }
    }
    return largest;
}

