public int findLargestSubstring(List<String> strings) {
        boolean[][] dp = new boolean[strings.size()][strings.get(0).length()];
        for (int i = 1; i < strings.size(); i++) {
            for (int j = 1; j < strings.get(i).length(); j++) {
                if (strings.get(i - 1).charAt(j) == strings.get(i).charAt(j)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
                }
            }
        }

        int count = 0;
        for (int i = 0; i < strings.size(); i++) {
            for (int j = 0; j < strings.get(i).length(); j++) {
                if (dp[i][j]) {
                    count = Math.max(count, strings.get(i).length() - j);
                }
            }
        }

        return count;
    }

