    queue.offer(start);
    // While the queue is not empty
    while (!queue.isEmpty()) {
        // Dequeue the front vertex
        int[] frontVertix = queue.poll();
        // If the front vertex is the ending n-tersection
        if (Arrays.equals(frontVertix, end)) {
