public static String appx(String word1, String word2) {
    // Calculate the number of common letters
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    // Calculate the approximate value
    int denominator = word1.length() + word2.length();
    int numerator = commonLetters;
    Double approximateValue = (double)numerator / denominator;

    // Reduce the fraction to its simplest form
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    // Return the approximate value as a reduced fraction
    return numerator + "/" + denominator;
}

