public int minOperations(String[] logs) {

  HashMap<String, Integer> folders = new HashMap<>(); // maps folder names to their nesting level
  int currentNestingLevel = 0; // current nesting level based on the list of logs
  int minDepth = 0; // minimum nesting level that has been reached so far
  int steps = 0; // number of steps taken

  for (String log : logs) {
    if (log.equals("../")) { // "../" operation
      currentNestingLevel--;
      steps++;
    } else { // add or remove an entry log for a folder
      if (folders.containsKey(log)) {
        folders.remove(log);
      } else {
        folders.put(log, currentNestingLevel);
      }
      currentNestingLevel = Math.max(currentNestingLevel, folders.get(log));
    }
    minDepth = Math.min(minDepth, currentNestingLevel);
  }

  return currentNestingLevel == 0 ? 0 : steps - minDepth + 1;
}

