    // Initialize a hash map to store the counts of each element
    Map<Integer, Integer> counts = new HashMap<>();

    // Iterate over the input array and increment the count of each element
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }

    // Find the element with a count of 1
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            return entry.getKey();
        }
    }

    // If no element has a count of 1, then there is no single number in the input array
    return -1;
}

